  "/teams/{team_id}": {
    /**
     * Get Team by ID
     * @description Returns a team if a valid ID is provided.
     */
    get: operations["get_team"];
    /**
     * Modify a Team
     * @description Modifies a team's information and settings if a valid ID and body are provided.
     */
    put: operations["update_team"];
    /**
     * Delete Team by ID
     * @description Deletes a team if a valid ID is provided.
     */
    delete: operations["delete_team"];
    /**
     * Update Team
     * @description Update a team.
     *
     * Rails' ``resources :teams`` (routes.rb:88) maps BOTH PUT and PATCH to
     * TeamsController#update, so both are registered here with identical
     * authorization, validation, response and side effects.
     *
     * Matches Rails:
     *     def update
     *       input = (validate_body_json Team).symbolize_keys
     *
     *       @team = Team.find_by_id(params[:id])
     *       raise Api::V1::ApiError.new(:not_found) if @team.nil?
     *       authorize! :manage, @team
     *
     *       @team.update_mutable!(request, current_user, input)
     *       render "show"
     *     end
     */
    patch: operations["teams_update_team"];
  };
