        "grok.pattern"?: "%{SYSLOGBASE}" | "%{COMBINEDAPACHELOG}" | "%{NAGIOSLOGLINE}" | "%{POSTGRESQL}" | "%{REDISLOG}" | "%{JAVASTACKTRACEPART}";
